window.LabFlowKnowledgeBundle={"entries":[{"id":"concept.perovskite-solar-cell","kind":"concept","title":"Metal-halide perovskite solar cell","aliases":["PSC","perovskite PV","perovskite photovoltaic"],"tags":["perovskite","photovoltaic","device"],"summary":"A thin-film photovoltaic device using a metal-halide perovskite semiconductor as the light-absorbing layer.","facts":["Perovskite absorbers can be integrated in multiple planar and mesoscopic device architectures.","Charge-selective contacts on the two sides of the absorber extract electrons and holes."],"cautions":["The term PSC does not identify one unique stack, composition or fabrication route."],"related_ids":["architecture.nip-planar","architecture.pin-inverted"],"sources":[{"title":"The emergence of perovskite solar cells","authors":"M. A. Green, A. Ho-Baillie, H. J. Snaith","year":2014,"citation":"Nature Photonics 8, 506–514 (2014)","doi":"10.1038/nphoton.2014.134","url":"","note":""},{"title":"Promises and challenges of perovskite solar cells","authors":"J.-P. Correa-Baena et al.","year":2017,"citation":"Science 358, 739–744 (2017)","doi":"10.1126/science.aam6323","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.pce","kind":"concept","title":"Power conversion efficiency","aliases":["PCE","efficiency","eta"],"tags":["JV","photovoltaic","metric","efficiency"],"summary":"PCE is the ratio of electrical power delivered at the maximum-power point to incident optical power.","facts":["For a JV measurement, PCE is determined by Voc, Jsc and fill factor together with the incident irradiance.","A scan-derived PCE can be misleading when the JV response is strongly hysteretic or unstable."],"cautions":["Do not compare PCE values without checking illumination calibration, active area, scan protocol and stabilization conditions."],"related_ids":["concept.voc","concept.jsc","concept.fill-factor","concept.stabilized-power-output"],"sources":[{"title":"Photovoltaic solar cell technologies: analysing the state of the art","authors":"P. K. Nayak et al.","year":2019,"citation":"Nature Reviews Materials 4, 269–285 (2019)","doi":"10.1038/s41578-019-0097-0","url":"","note":""},{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.voc","kind":"concept","title":"Open-circuit voltage","aliases":["Voc","V_OC","open circuit voltage"],"tags":["JV","photovoltaic","metric","voltage"],"summary":"Voc is the terminal voltage under illumination when the external current is zero.","facts":["Voc is strongly affected by recombination losses and by the energetics/selectivity of contacts and interfaces."],"cautions":["Low Voc is not diagnostic of one unique defect or interface problem."],"related_ids":["diagnostic.low-voc","concept.nonradiative-recombination"],"sources":[{"title":"Minimizing Voltage Losses in Perovskite Solar Cells","authors":"P. Chen, Y. Bai, L. Wang","year":2021,"citation":"Small Structures 2, 2000050 (2021)","doi":"10.1002/sstr.202000050","url":"","note":""},{"title":"Nonradiative Recombination in Perovskite Solar Cells: The Role of Interfaces","authors":"C. M. Wolff et al.","year":2019,"citation":"Advanced Materials 31, 1902762 (2019)","doi":"10.1002/adma.201902762","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.jsc","kind":"concept","title":"Short-circuit current density","aliases":["Jsc","J_SC","short circuit current"],"tags":["JV","photovoltaic","metric","current"],"summary":"Jsc is the photocurrent density measured at zero applied terminal voltage.","facts":["Jsc depends on optical generation and on how effectively photogenerated carriers are collected."],"cautions":["A low Jsc can arise from optical, electrical, geometrical or measurement causes; JV alone rarely identifies which one."],"related_ids":["diagnostic.low-jsc","concept.series-resistance"],"sources":[{"title":"Photovoltaic solar cell technologies: analysing the state of the art","authors":"P. K. Nayak et al.","year":2019,"citation":"Nature Reviews Materials 4, 269–285 (2019)","doi":"10.1038/s41578-019-0097-0","url":"","note":""},{"title":"Promises and challenges of perovskite solar cells","authors":"J.-P. Correa-Baena et al.","year":2017,"citation":"Science 358, 739–744 (2017)","doi":"10.1126/science.aam6323","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.fill-factor","kind":"concept","title":"Fill factor","aliases":["FF","fill-factor"],"tags":["JV","photovoltaic","metric","power"],"summary":"Fill factor describes the squareness of the illuminated JV curve and relates maximum output power to Voc and Jsc.","facts":["FF losses can originate from resistive losses, recombination, transport limitations and departures from ideal diode behavior."],"cautions":["A low FF is a symptom, not a unique failure mechanism."],"related_ids":["diagnostic.low-ff","concept.series-resistance","concept.shunt-resistance"],"sources":[{"title":"Fill Factor Losses and Deviations from the Superposition Principle in Lead Halide Perovskite Solar Cells","authors":"D. Grabowski et al.","year":2022,"citation":"Solar RRL 6, 2200507 (2022)","doi":"10.1002/solr.202200507","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.series-resistance","kind":"concept","title":"Series resistance","aliases":["Rs","R_s","series resistance"],"tags":["JV","resistance","FF","transport"],"summary":"Series resistance represents resistive voltage losses along current-transport paths in the device and contacts.","facts":["Excessive series resistance tends to reduce fill factor and maximum power.","Transport-layer and contact resistance can contribute to the effective series resistance."],"cautions":["Extracted Rs can depend on the model and measurement method; treat simple slope estimates as approximations."],"related_ids":["diagnostic.high-series-resistance","concept.fill-factor"],"sources":[{"title":"Series Resistance Measurements of Perovskite Solar Cells Using Jsc–Voc Measurements","authors":"N. Mundhaas et al.","year":2019,"citation":"Solar RRL 3, 1800378 (2019)","doi":"10.1002/solr.201800378","url":"","note":""},{"title":"Fill Factor Losses and Deviations from the Superposition Principle in Lead Halide Perovskite Solar Cells","authors":"D. Grabowski et al.","year":2022,"citation":"Solar RRL 6, 2200507 (2022)","doi":"10.1002/solr.202200507","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.shunt-resistance","kind":"concept","title":"Shunt resistance","aliases":["Rsh","R_sh","shunt resistance"],"tags":["JV","resistance","leakage","FF"],"summary":"Shunt resistance represents parasitic leakage paths that bypass the intended photovoltaic junction.","facts":["Low effective shunt resistance can reduce fill factor and, when severe, can reduce Voc and useful current."],"cautions":["Apparent shunt-like behavior under illumination may also reflect transport and field-screening effects rather than a simple physical pinhole."],"related_ids":["diagnostic.low-shunt-resistance","concept.fill-factor"],"sources":[{"title":"Fill Factor Losses and Deviations from the Superposition Principle in Lead Halide Perovskite Solar Cells","authors":"D. Grabowski et al.","year":2022,"citation":"Solar RRL 6, 2200507 (2022)","doi":"10.1002/solr.202200507","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.jv-hysteresis","kind":"concept","title":"JV hysteresis","aliases":["IV hysteresis","J-V hysteresis","JV hysteresis","hysteresis"],"tags":["JV","measurement","hysteresis","ions"],"summary":"JV hysteresis is a dependence of the measured current-voltage response on scan direction, scan rate, preconditioning or measurement history.","facts":["Ion redistribution, trapping/detrapping and interfacial effects are among mechanisms associated with hysteretic response.","Forward and reverse scans can yield different apparent photovoltaic parameters."],"cautions":["Absence of visible hysteresis in one scan protocol does not prove stationary behavior."],"related_ids":["diagnostic.forward-reverse-mismatch","diagnostic.scan-rate-sensitivity","concept.stabilized-power-output"],"sources":[{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""},{"title":"Origin and alleviation of J-V hysteresis in perovskite solar cells: A short review","authors":"","year":2021,"citation":"Catalysis Today 374, 86–101 (2021)","doi":"10.1016/j.cattod.2020.12.025","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.stabilized-power-output","kind":"concept","title":"Stabilized power output","aliases":["SPO","steady-state PCE","stabilized PCE","MPP tracking","MPPT"],"tags":["JV","MPP","measurement","stability"],"summary":"A time-dependent power measurement near or at the maximum-power point used to verify that scan-derived efficiency reflects sustained device output.","facts":["Maximum-power-point tracking is useful for evaluating operational output when JV scans are affected by dynamic response."],"cautions":["A short stabilization measurement is not equivalent to a long-term stability test."],"related_ids":["concept.pce","concept.jv-hysteresis","diagnostic.mpp-scan-mismatch"],"sources":[{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""},{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.nonradiative-recombination","kind":"concept","title":"Non-radiative recombination","aliases":["nonradiative recombination","trap-assisted recombination","SRH recombination"],"tags":["Voc","recombination","interface","defects"],"summary":"Recombination pathway in which electron-hole pairs recombine without useful photon emission, contributing to voltage and efficiency losses.","facts":["In high-performance perovskite devices, interfaces with charge-transport layers can be important sites of non-radiative recombination."],"cautions":["The dominant recombination pathway cannot be identified from Voc alone."],"related_ids":["diagnostic.low-voc","concept.voc"],"sources":[{"title":"Nonradiative Recombination in Perovskite Solar Cells: The Role of Interfaces","authors":"C. M. Wolff et al.","year":2019,"citation":"Advanced Materials 31, 1902762 (2019)","doi":"10.1002/adma.201902762","url":"","note":""},{"title":"Minimizing Voltage Losses in Perovskite Solar Cells","authors":"P. Chen, Y. Bai, L. Wang","year":2021,"citation":"Small Structures 2, 2000050 (2021)","doi":"10.1002/sstr.202000050","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"architecture.nip-planar","kind":"architecture","title":"Planar n-i-p perovskite architecture","aliases":["n-i-p","regular planar","normal planar"],"tags":["architecture","n-i-p","planar","perovskite"],"summary":"Regular planar architecture in which the illuminated-side electron-selective contact precedes the perovskite absorber and the hole-selective contact follows it.","facts":["Common ETL families include metal oxides such as SnO2 or TiO2.","Common hole-selective materials include spiro-OMeTAD and PTAA, among others."],"cautions":["Material order alone does not determine exact energetics, thicknesses or processing conditions."],"related_ids":["material.sno2","material.tio2","material.spiro-ometad","material.ptaa"],"sources":[{"title":"The emergence of perovskite solar cells","authors":"M. A. Green, A. Ho-Baillie, H. J. Snaith","year":2014,"citation":"Nature Photonics 8, 506–514 (2014)","doi":"10.1038/nphoton.2014.134","url":"","note":""},{"title":"Promises and challenges of perovskite solar cells","authors":"J.-P. Correa-Baena et al.","year":2017,"citation":"Science 358, 739–744 (2017)","doi":"10.1126/science.aam6323","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"architecture.nip-mesoporous","kind":"architecture","title":"Mesoporous n-i-p perovskite architecture","aliases":["mesoscopic n-i-p","mesoporous PSC","mesoscopic PSC"],"tags":["architecture","n-i-p","mesoporous","TiO2"],"summary":"Regular n-i-p architecture that includes a mesoporous scaffold, historically often based on TiO2, beneath or within part of the perovskite absorber.","facts":["Mesoporous and planar regular architectures are distinct device families and should not be conflated when reconstructing a stack."],"cautions":["A TiO2-containing device is not necessarily mesoporous; morphology and fabrication evidence are needed."],"related_ids":["material.tio2","architecture.nip-planar"],"sources":[{"title":"The emergence of perovskite solar cells","authors":"M. A. Green, A. Ho-Baillie, H. J. Snaith","year":2014,"citation":"Nature Photonics 8, 506–514 (2014)","doi":"10.1038/nphoton.2014.134","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"architecture.pin-inverted","kind":"architecture","title":"Inverted p-i-n perovskite architecture","aliases":["p-i-n","inverted PSC","inverted perovskite"],"tags":["architecture","p-i-n","inverted","perovskite"],"summary":"Inverted architecture in which the illuminated-side hole-selective contact precedes the perovskite absorber and the electron-selective contact follows it.","facts":["Common hole-selective layers include PTAA, NiOx and carbazole-phosphonic-acid SAMs.","C60 and PCBM are common fullerene-based electron-selective materials in inverted devices."],"cautions":["The exact buffer layer and metal electrode depend on the device implementation."],"related_ids":["material.ptaa","material.niox","material.2pacz","material.meo-2pacz","material.c60","material.pcbm"],"sources":[{"title":"Recent Advances in Inverted Perovskite Solar Cells: Designing and Fabrication","authors":"","year":2022,"citation":"International Journal of Molecular Sciences 23, 11792 (2022)","doi":"10.3390/ijms231911792","url":"","note":""},{"title":"Self-assembled monolayers (SAMs) in inverted perovskite solar cells and their tandem photovoltaics application","authors":"","year":2024,"citation":"Interdisciplinary Materials (2024)","doi":"10.1002/idm2.12145","url":"","note":""},{"title":"Key advances in perovskite solar cells in 2025","authors":"N.-G. Park, H. J. Snaith, T. Miyasaka","year":2026,"citation":"Nature Reviews Clean Technology 2, 6–7 (2026)","doi":"10.1038/s44359-025-00128-z","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"architecture.selective-contacts","kind":"architecture","title":"Charge-selective contacts in perovskite photovoltaics","aliases":["ETL HTL","electron transport layer","hole transport layer","selective contact"],"tags":["architecture","ETL","HTL","interface","transport"],"summary":"Electron-selective and hole-selective contacts are used to extract one carrier type while limiting losses associated with the opposite carrier.","facts":["Energy-level alignment, carrier transport, optical transmission and interfacial recombination are important considerations when selecting transport layers."],"cautions":["Labels such as ETL and HTL describe a functional role; the same material family can behave differently depending on interface, doping and processing."],"related_ids":["material.sno2","material.c60","material.ptaa","material.niox"],"sources":[{"title":"PTAA as Efficient Hole Transport Materials in Perovskite Solar Cells: A Review","authors":"Y. Wang et al.","year":2022,"citation":"Solar RRL 6, 2200234 (2022)","doi":"10.1002/solr.202200234","url":"","note":""},{"title":"Review of progress in inorganic electron transport layers for perovskite solar cell applications","authors":"","year":2025,"citation":"Applied Physics A (2025)","doi":"10.1007/s00339-025-08975-0","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.sno2","kind":"material","title":"SnO2","aliases":["SnO2","tin oxide","tin dioxide"],"tags":["ETL","electron transport","n-i-p","oxide"],"summary":"Tin oxide is a widely used inorganic electron-selective/transport material in perovskite photovoltaics, especially in regular n-i-p devices.","facts":["SnO2 is attractive for low-temperature processing, optical transparency and electron-selective contact formation.","Its interface with the perovskite can influence extraction, recombination and device stability."],"cautions":["The presence of SnO2 does not by itself establish a complete n-i-p stack or a specific deposition route."],"related_ids":["architecture.nip-planar","diagnostic.low-voc","diagnostic.high-series-resistance"],"sources":[{"title":"Advancing SnO2 Electron Transport Layer for Efficient Perovskite Photovoltaics: A Critical Review","authors":"Y. Wang et al.","year":2025,"citation":"ACS Applied Materials & Interfaces 17, 27651–27670 (2025)","doi":"10.1021/acsami.5c03204","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.tio2","kind":"material","title":"TiO2","aliases":["TiO2","titania","titanium dioxide"],"tags":["ETL","electron transport","n-i-p","mesoporous","oxide"],"summary":"Titanium dioxide is a classic electron-selective material used in regular perovskite solar-cell architectures, including planar and mesoporous variants.","facts":["TiO2 has been used as compact and mesoporous electron-selective layers in perovskite photovoltaics."],"cautions":["A TiO2 layer may be compact, mesoporous or part of a multilayer contact; infer morphology only from experiment evidence."],"related_ids":["architecture.nip-planar","architecture.nip-mesoporous"],"sources":[{"title":"The emergence of perovskite solar cells","authors":"M. A. Green, A. Ho-Baillie, H. J. Snaith","year":2014,"citation":"Nature Photonics 8, 506–514 (2014)","doi":"10.1038/nphoton.2014.134","url":"","note":""},{"title":"Review of progress in inorganic electron transport layers for perovskite solar cell applications","authors":"","year":2025,"citation":"Applied Physics A (2025)","doi":"10.1007/s00339-025-08975-0","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.c60","kind":"material","title":"C60 fullerene","aliases":["C60","fullerene","buckminsterfullerene"],"tags":["ETL","electron transport","p-i-n","fullerene"],"summary":"C60 is a fullerene electron-selective material widely used in inverted p-i-n perovskite solar cells.","facts":["C60 can efficiently extract electrons from perovskite and is commonly deposited on top of the absorber in inverted stacks."],"cautions":["C60 thickness, coverage and interfaces matter; its mere presence does not establish a complete stack."],"related_ids":["architecture.pin-inverted","material.bcp","material.pcbm"],"sources":[{"title":"Functionalized fullerene: a key driver for high performance inverted perovskite solar cell","authors":"X. Zhang et al.","year":2025,"citation":"Journal of Energy Chemistry 111, 30–50 (2025)","doi":"10.1016/j.jechem.2025.07.050","url":"","note":""},{"title":"Recent Advances in Inverted Perovskite Solar Cells: Designing and Fabrication","authors":"","year":2022,"citation":"International Journal of Molecular Sciences 23, 11792 (2022)","doi":"10.3390/ijms231911792","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.pcbm","kind":"material","title":"PCBM","aliases":["PCBM","PC61BM","[6,6]-phenyl-C61-butyric acid methyl ester"],"tags":["ETL","electron transport","p-i-n","fullerene"],"summary":"PCBM is a soluble fullerene derivative commonly used as an electron-selective/transport layer in inverted perovskite solar cells.","facts":["PCBM combines fullerene electron affinity with solution processability and has a long history in inverted PSCs."],"cautions":["Solution compatibility and overlayer processing must be considered because organic transport layers can be sensitive to subsequent solvents."],"related_ids":["architecture.pin-inverted","material.c60"],"sources":[{"title":"Functionalized fullerene: a key driver for high performance inverted perovskite solar cell","authors":"X. Zhang et al.","year":2025,"citation":"Journal of Energy Chemistry 111, 30–50 (2025)","doi":"10.1016/j.jechem.2025.07.050","url":"","note":""},{"title":"Recent Advances in Inverted Perovskite Solar Cells: Designing and Fabrication","authors":"","year":2022,"citation":"International Journal of Molecular Sciences 23, 11792 (2022)","doi":"10.3390/ijms231911792","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.bcp","kind":"material","title":"Bathocuproine (BCP)","aliases":["BCP","bathocuproine"],"tags":["buffer","electron contact","p-i-n","C60","PCBM"],"summary":"BCP is commonly used as a thin cathode-side buffer/interlayer in fullerene-based inverted perovskite device stacks.","facts":["BCP often appears between a fullerene electron-transport layer and a metal electrode in inverted PSC literature."],"cautions":["BCP is not mandatory for all C60/PCBM devices; alternative buffer/interfacial layers are common."],"related_ids":["material.c60","material.pcbm","architecture.pin-inverted"],"sources":[{"title":"Self-assembled monolayers (SAMs) in inverted perovskite solar cells and their tandem photovoltaics application","authors":"","year":2024,"citation":"Interdisciplinary Materials (2024)","doi":"10.1002/idm2.12145","url":"","note":""},{"title":"Recent Advances in Inverted Perovskite Solar Cells: Designing and Fabrication","authors":"","year":2022,"citation":"International Journal of Molecular Sciences 23, 11792 (2022)","doi":"10.3390/ijms231911792","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.ptaa","kind":"material","title":"PTAA","aliases":["PTAA","poly(triarylamine)","poly[bis(4-phenyl)(2,4,6-trimethylphenyl)amine]"],"tags":["HTL","hole transport","n-i-p","p-i-n","polymer"],"summary":"Poly(triarylamine) is a widely used organic hole-selective/transport material in perovskite solar cells.","facts":["PTAA has been used in both regular and inverted PSC architectures.","Its wetting, doping and interface properties can materially affect device behavior."],"cautions":["Do not assume dopants or concentrations from the material name alone."],"related_ids":["architecture.nip-planar","architecture.pin-inverted"],"sources":[{"title":"PTAA as Efficient Hole Transport Materials in Perovskite Solar Cells: A Review","authors":"Y. Wang et al.","year":2022,"citation":"Solar RRL 6, 2200234 (2022)","doi":"10.1002/solr.202200234","url":"","note":""},{"title":"Lessons learned from spiro-OMeTAD and PTAA in perovskite solar cells","authors":"F. M. Rombach, S. A. Haque, T. J. Macdonald","year":2021,"citation":"Energy & Environmental Science 14, 5161–5190 (2021)","doi":"10.1039/D1EE02095A","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.spiro-ometad","kind":"material","title":"Spiro-OMeTAD","aliases":["spiro-OMeTAD","Spiro OMeTAD","Spiro"],"tags":["HTL","hole transport","n-i-p","organic"],"summary":"Spiro-OMeTAD is a benchmark small-molecule hole-transport material widely used on top of perovskite absorbers in regular n-i-p devices.","facts":["Spiro-OMeTAD has enabled high-efficiency n-i-p devices and is commonly used with conductivity-enhancing additives/dopants."],"cautions":["Do not infer the dopant package, oxidation state or formulation without experiment evidence; these details affect stability and conductivity."],"related_ids":["architecture.nip-planar","material.ptaa"],"sources":[{"title":"Lessons learned from spiro-OMeTAD and PTAA in perovskite solar cells","authors":"F. M. Rombach, S. A. Haque, T. J. Macdonald","year":2021,"citation":"Energy & Environmental Science 14, 5161–5190 (2021)","doi":"10.1039/D1EE02095A","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.niox","kind":"material","title":"NiOx","aliases":["NiOx","NiO","nickel oxide"],"tags":["HTL","hole transport","p-i-n","oxide"],"summary":"Nickel oxide is an inorganic hole-selective contact frequently used in inverted p-i-n perovskite solar cells.","facts":["NiOx can serve as a robust inorganic hole-selective layer and is also combined with molecular interlayers/SAMs."],"cautions":["Surface chemistry, stoichiometry and treatment can strongly affect NiOx/perovskite interfaces."],"related_ids":["architecture.pin-inverted","material.2pacz","material.meo-2pacz"],"sources":[{"title":"A brief review of hole transporting materials commonly used in perovskite solar cells","authors":"","year":2021,"citation":"Rare Metals (2021)","doi":"10.1007/s12598-020-01691-z","url":"","note":""},{"title":"Self-assembled monolayers (SAMs) in inverted perovskite solar cells and their tandem photovoltaics application","authors":"","year":2024,"citation":"Interdisciplinary Materials (2024)","doi":"10.1002/idm2.12145","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.pedot-pss","kind":"material","title":"PEDOT:PSS","aliases":["PEDOT:PSS","PEDOT PSS"],"tags":["HTL","hole transport","p-i-n","polymer"],"summary":"PEDOT:PSS is a conductive polymer blend historically used as a hole-selective layer in inverted perovskite solar cells.","facts":["PEDOT:PSS is solution-processable and has been widely used in early and low-temperature inverted architectures."],"cautions":["Its acidity, energetics and interface properties can limit performance in some perovskite systems; do not treat it as interchangeable with PTAA, NiOx or SAMs."],"related_ids":["architecture.pin-inverted","material.ptaa","material.niox"],"sources":[{"title":"A brief review of hole transporting materials commonly used in perovskite solar cells","authors":"","year":2021,"citation":"Rare Metals (2021)","doi":"10.1007/s12598-020-01691-z","url":"","note":""},{"title":"Recent Advances in Inverted Perovskite Solar Cells: Designing and Fabrication","authors":"","year":2022,"citation":"International Journal of Molecular Sciences 23, 11792 (2022)","doi":"10.3390/ijms231911792","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.2pacz","kind":"material","title":"2PACz","aliases":["2PACz","2-(9H-carbazol-9-yl)ethylphosphonic acid"],"tags":["SAM","HTL","hole selective","p-i-n","phosphonic acid"],"summary":"2PACz is a carbazole-phosphonic-acid self-assembled molecule used as a hole-selective contact, especially in inverted perovskite photovoltaics.","facts":["Carbazole-phosphonic-acid SAMs can form very thin hole-selective contacts on conductive oxides with low parasitic absorption."],"cautions":["SAM coverage, substrate surface preparation and wetting can affect subsequent perovskite film formation."],"related_ids":["architecture.pin-inverted","material.meo-2pacz","material.ito","material.niox"],"sources":[{"title":"Self-assembled monolayers for perovskite solar cells","authors":"","year":2025,"citation":"Review of Materials Research 1, 100017 (2025)","doi":"10.1016/j.revmat.2025.100017","url":"","note":""},{"title":"Self-assembled monolayers (SAMs) in inverted perovskite solar cells and their tandem photovoltaics application","authors":"","year":2024,"citation":"Interdisciplinary Materials (2024)","doi":"10.1002/idm2.12145","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.meo-2pacz","kind":"material","title":"MeO-2PACz","aliases":["MeO-2PACz","MeO2PACz"],"tags":["SAM","HTL","hole selective","p-i-n","phosphonic acid"],"summary":"MeO-2PACz is a methoxy-substituted carbazole-phosphonic-acid self-assembled molecule used as a hole-selective contact in inverted PSCs and tandems.","facts":["MeO-2PACz is part of the widely used carbazole-phosphonic-acid SAM family for inverted perovskite devices."],"cautions":["Do not assume that 2PACz and MeO-2PACz are interchangeable; energetics, wetting and film formation can differ."],"related_ids":["architecture.pin-inverted","material.2pacz","material.ito"],"sources":[{"title":"Self-assembled monolayers for perovskite solar cells","authors":"","year":2025,"citation":"Review of Materials Research 1, 100017 (2025)","doi":"10.1016/j.revmat.2025.100017","url":"","note":""},{"title":"Self-assembled monolayers (SAMs) in inverted perovskite solar cells and their tandem photovoltaics application","authors":"","year":2024,"citation":"Interdisciplinary Materials (2024)","doi":"10.1002/idm2.12145","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.ito","kind":"material","title":"ITO","aliases":["ITO","indium tin oxide"],"tags":["TCO","transparent electrode","substrate","contact"],"summary":"Indium tin oxide is a transparent conductive oxide commonly used as a front electrode/substrate coating in thin-film perovskite devices.","facts":["ITO can support either electron- or hole-selective contact stacks depending on the architecture deposited on it."],"cautions":["ITO does not determine whether a device is n-i-p or p-i-n."],"related_ids":["architecture.nip-planar","architecture.pin-inverted","material.2pacz"],"sources":[{"title":"The emergence of perovskite solar cells","authors":"M. A. Green, A. Ho-Baillie, H. J. Snaith","year":2014,"citation":"Nature Photonics 8, 506–514 (2014)","doi":"10.1038/nphoton.2014.134","url":"","note":""},{"title":"Recent Advances in Inverted Perovskite Solar Cells: Designing and Fabrication","authors":"","year":2022,"citation":"International Journal of Molecular Sciences 23, 11792 (2022)","doi":"10.3390/ijms231911792","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.fto","kind":"material","title":"FTO","aliases":["FTO","fluorine doped tin oxide"],"tags":["TCO","transparent electrode","substrate","contact"],"summary":"Fluorine-doped tin oxide is a transparent conductive oxide widely used as a front electrode in perovskite solar-cell research.","facts":["FTO is especially common in regular architectures using metal-oxide electron-selective layers."],"cautions":["FTO is also compatible with other architectures; do not infer the stack from the substrate alone."],"related_ids":["architecture.nip-planar","material.sno2","material.tio2"],"sources":[{"title":"The emergence of perovskite solar cells","authors":"M. A. Green, A. Ho-Baillie, H. J. Snaith","year":2014,"citation":"Nature Photonics 8, 506–514 (2014)","doi":"10.1038/nphoton.2014.134","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.gold","kind":"material","title":"Gold electrode","aliases":["Au","gold"],"tags":["electrode","metal","contact"],"summary":"Gold is a metal electrode material commonly used as a top contact in laboratory perovskite solar cells.","facts":["Gold appears frequently in regular n-i-p laboratory stacks and in some other device configurations."],"cautions":["Electrode choice affects energetics, diffusion and stability; gold is not universally optimal or required."],"related_ids":["architecture.nip-planar"],"sources":[{"title":"The emergence of perovskite solar cells","authors":"M. A. Green, A. Ho-Baillie, H. J. Snaith","year":2014,"citation":"Nature Photonics 8, 506–514 (2014)","doi":"10.1038/nphoton.2014.134","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.silver","kind":"material","title":"Silver electrode","aliases":["Ag","silver"],"tags":["electrode","metal","contact"],"summary":"Silver is a common metal electrode used in many perovskite device architectures, including inverted stacks.","facts":["Silver is often paired with cathode-side electron-selective/buffer layers in inverted devices."],"cautions":["Metal/perovskite stacks can suffer interfacial reactions or ion migration; exact stability depends on barrier layers and operating conditions."],"related_ids":["architecture.pin-inverted","material.bcp"],"sources":[{"title":"Recent Advances in Inverted Perovskite Solar Cells: Designing and Fabrication","authors":"","year":2022,"citation":"International Journal of Molecular Sciences 23, 11792 (2022)","doi":"10.3390/ijms231911792","url":"","note":""},{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.copper","kind":"material","title":"Copper electrode","aliases":["Cu","copper"],"tags":["electrode","metal","contact"],"summary":"Copper is used as a metal top electrode in some inverted perovskite solar-cell stacks and tandem configurations.","facts":["Copper appears in literature stacks combined with fullerene/buffer electron-selective contacts."],"cautions":["Copper is not a default electrode; diffusion barriers and interfacial design can matter for stability."],"related_ids":["architecture.pin-inverted","material.c60","material.bcp"],"sources":[{"title":"Self-assembled monolayers (SAMs) in inverted perovskite solar cells and their tandem photovoltaics application","authors":"","year":2024,"citation":"Interdisciplinary Materials (2024)","doi":"10.1002/idm2.12145","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.carbon-electrode","kind":"material","title":"Carbon electrode","aliases":["carbon electrode","graphite electrode","carbon contact"],"tags":["electrode","carbon","printable","contact"],"summary":"Carbon-based contacts can replace vacuum-deposited metals in some perovskite architectures and are attractive for printable device concepts.","facts":["Carbon electrodes have been explored in perovskite solar cells as conductive contacts with potential processing and stability advantages."],"cautions":["Carbon-based architectures can differ substantially from conventional planar metal-contact stacks."],"related_ids":["concept.perovskite-solar-cell"],"sources":[{"title":"Carbon Materials in Perovskite Solar Cells: Prospects and Future Challenges","authors":"V. Ferguson et al.","year":2019,"citation":"Energy & Environmental Materials (2019)","doi":"10.1002/eem2.12035","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"material.mixed-cation-halide-perovskite","kind":"material","title":"Mixed-cation / mixed-halide lead perovskite absorber","aliases":["mixed cation perovskite","mixed halide perovskite","FA MA Cs perovskite","triple cation"],"tags":["absorber","perovskite","FA","MA","Cs","I","Br"],"summary":"A family of lead-halide perovskite absorbers in which multiple A-site cations and/or multiple halides are combined to tune material and device properties.","facts":["FA, MA and Cs are commonly used A-site cations in mixed compositions; I and Br are common halides used for bandgap/composition tuning."],"cautions":["Composition must be taken from source evidence; a generic “perovskite” label does not justify inferring exact cation or halide fractions."],"related_ids":["formulation.perovskite-precursor-family","formulation.mixed-cation-composition","formulation.mixed-halide-composition"],"sources":[{"title":"Progress on Perovskite Materials and Solar Cells with Mixed Cations and Halide Anions","authors":"L. K. Ono et al.","year":2017,"citation":"ACS Applied Materials & Interfaces 9, 30197–30246 (2017)","doi":"10.1021/acsami.7b06001","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"formulation.perovskite-precursor-family","kind":"formulation","title":"Lead-halide perovskite precursor family","aliases":["perovskite precursor","precursor ink","lead halide precursor"],"tags":["precursor","PbI2","FAI","MAI","CsI","solution"],"summary":"Solution-processed lead-halide perovskites are commonly prepared from lead-halide precursor salts combined with organic and/or inorganic halide salts.","facts":["PbI2 is a common lead source for iodide-rich lead perovskites; FAI, MAI and Cs-containing salts are examples of A-site precursor families."],"cautions":["Do not infer exact stoichiometry, concentration, excess precursor or additive package without explicit recipe/evidence."],"related_ids":["material.mixed-cation-halide-perovskite","formulation.dmf-dmso-solvent-system"],"sources":[{"title":"Progress on Perovskite Materials and Solar Cells with Mixed Cations and Halide Anions","authors":"L. K. Ono et al.","year":2017,"citation":"ACS Applied Materials & Interfaces 9, 30197–30246 (2017)","doi":"10.1021/acsami.7b06001","url":"","note":""},{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"formulation.dmf-dmso-solvent-system","kind":"formulation","title":"DMF/DMSO perovskite solvent system","aliases":["DMF DMSO","DMF/DMSO","dimethylformamide dimethyl sulfoxide"],"tags":["solvent","perovskite ink","DMF","DMSO","solution"],"summary":"DMF and DMSO are widely used polar aprotic solvents/co-solvents for solution processing of lead-halide perovskite precursor inks.","facts":["Solvent coordination and solvent ratios influence precursor complexes, drying, nucleation and film morphology."],"cautions":["The solvent pair does not establish a universal ratio or process window; these are formulation- and process-dependent."],"related_ids":["formulation.perovskite-precursor-family","process.spin-coating","process.antisolvent-quench"],"sources":[{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"formulation.mixed-cation-composition","kind":"formulation","title":"Mixed A-site cation perovskite composition","aliases":["mixed cation","FA/MA","FA/Cs","FA/MA/Cs","triple cation"],"tags":["composition","FA","MA","Cs","absorber"],"summary":"Perovskite compositions may combine cations such as FA, MA and Cs to tune phase stability, crystallization and optoelectronic properties.","facts":["Mixed-cation engineering is a well-established strategy in lead-halide perovskite photovoltaics."],"cautions":["Do not infer the exact cation fractions from device performance or architecture."],"related_ids":["material.mixed-cation-halide-perovskite","formulation.mixed-halide-composition"],"sources":[{"title":"Progress on Perovskite Materials and Solar Cells with Mixed Cations and Halide Anions","authors":"L. K. Ono et al.","year":2017,"citation":"ACS Applied Materials & Interfaces 9, 30197–30246 (2017)","doi":"10.1021/acsami.7b06001","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"formulation.mixed-halide-composition","kind":"formulation","title":"Mixed-halide perovskite composition","aliases":["mixed halide","I/Br","iodide bromide"],"tags":["composition","I","Br","bandgap","absorber"],"summary":"Perovskite absorbers may mix iodide and bromide to tune bandgap and material properties.","facts":["Changing halide composition is a major route for bandgap tuning, particularly relevant to tandem photovoltaics."],"cautions":["Mixed-halide compositions can exhibit light- or bias-related compositional dynamics; exact behavior depends on formulation and interfaces."],"related_ids":["material.mixed-cation-halide-perovskite","formulation.mixed-cation-composition"],"sources":[{"title":"Progress on Perovskite Materials and Solar Cells with Mixed Cations and Halide Anions","authors":"L. K. Ono et al.","year":2017,"citation":"ACS Applied Materials & Interfaces 9, 30197–30246 (2017)","doi":"10.1021/acsami.7b06001","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"formulation.antisolvent-assisted-crystallization","kind":"formulation","title":"Antisolvent-assisted crystallization","aliases":["antisolvent method","anti-solvent","solvent quench"],"tags":["crystallization","spin coating","antisolvent","film formation"],"summary":"A film-formation strategy in which an antisolvent is introduced during solution deposition to rapidly alter solvent quality and trigger perovskite nucleation/crystallization.","facts":["Antisolvent choice and timing strongly affect nucleation, morphology and reproducibility.","Common historical antisolvents include chlorobenzene and toluene, while greener alternatives are actively investigated."],"cautions":["Antisolvent identity, volume and timing are recipe-specific and should not be inferred from the generic method."],"related_ids":["process.antisolvent-quench","process.spin-coating"],"sources":[{"title":"Advances in Metal Halide Perovskite Film Preparation: The Role of Anti-Solvent Treatment","authors":"","year":2021,"citation":"Small Methods 5, 2100046 (2021)","doi":"10.1002/smtd.202100046","url":"","note":""},{"title":"Green anti-solvent engineering for high-efficiency and environmentally friendly perovskite solar cells","authors":"Y. Yang et al.","year":2024,"citation":"RSC Advances 14, 32370–32388 (2024)","doi":"10.1039/D4RA05082G","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"formulation.interface-passivation","kind":"formulation","title":"Interface passivation strategy","aliases":["passivation","surface passivation","interface modifier"],"tags":["interface","passivation","Voc","recombination"],"summary":"Use of molecular or ionic treatments/additives to reduce electrically active defects and non-radiative recombination at perovskite interfaces.","facts":["Reducing interfacial non-radiative recombination is a major route to improving Voc and device performance."],"cautions":["A passivation treatment can alter energetics, transport, wetting or stability as well as defect density; effects are chemistry-specific."],"related_ids":["concept.nonradiative-recombination","diagnostic.low-voc"],"sources":[{"title":"Nonradiative Recombination in Perovskite Solar Cells: The Role of Interfaces","authors":"C. M. Wolff et al.","year":2019,"citation":"Advanced Materials 31, 1902762 (2019)","doi":"10.1002/adma.201902762","url":"","note":""},{"title":"Minimizing Voltage Losses in Perovskite Solar Cells","authors":"P. Chen, Y. Bai, L. Wang","year":2021,"citation":"Small Structures 2, 2000050 (2021)","doi":"10.1002/sstr.202000050","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"process.solution-deposition","kind":"process","title":"Solution deposition","aliases":["solution processing","solution coated","wet coating"],"tags":["fabrication","solution","coating"],"summary":"Thin-film fabrication from a liquid precursor or material solution, encompassing spin coating and scalable coating methods.","facts":["Many perovskite absorbers and organic transport layers are compatible with solution processing."],"cautions":["Solution deposition does not imply one specific coating method, solvent, concentration or atmosphere."],"related_ids":["process.spin-coating","formulation.dmf-dmso-solvent-system"],"sources":[{"title":"Promises and challenges of perovskite solar cells","authors":"J.-P. Correa-Baena et al.","year":2017,"citation":"Science 358, 739–744 (2017)","doi":"10.1126/science.aam6323","url":"","note":""},{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"process.spin-coating","kind":"process","title":"Spin coating","aliases":["spin coat","spincoating","spin-coating"],"tags":["fabrication","solution","coating","perovskite"],"summary":"Laboratory thin-film deposition method in which centrifugal flow and solvent evaporation form a coating from a dispensed solution.","facts":["Spin coating is widely used for perovskite absorbers, transport layers and molecular interlayers in research-scale devices."],"cautions":["Spin speed, duration, dispense mode and environment are material-specific recipe parameters, not universal defaults."],"related_ids":["process.antisolvent-quench","formulation.dmf-dmso-solvent-system"],"sources":[{"title":"Advances in Metal Halide Perovskite Film Preparation: The Role of Anti-Solvent Treatment","authors":"","year":2021,"citation":"Small Methods 5, 2100046 (2021)","doi":"10.1002/smtd.202100046","url":"","note":""},{"title":"Self-assembled monolayers (SAMs) in inverted perovskite solar cells and their tandem photovoltaics application","authors":"","year":2024,"citation":"Interdisciplinary Materials (2024)","doi":"10.1002/idm2.12145","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"process.antisolvent-quench","kind":"process","title":"Antisolvent quench during coating","aliases":["antisolvent drip","anti-solvent drip","solvent quench"],"tags":["fabrication","crystallization","spin coating","antisolvent"],"summary":"Application of an antisolvent during wet-film formation to rapidly change supersaturation and crystallization kinetics.","facts":["The method can promote dense, uniform perovskite films when timing and solvent interactions are well controlled."],"cautions":["Poorly matched solvent/antisolvent conditions can damage film formation; never infer a safe process recipe solely from this KB entry."],"related_ids":["formulation.antisolvent-assisted-crystallization","process.spin-coating"],"sources":[{"title":"Advances in Metal Halide Perovskite Film Preparation: The Role of Anti-Solvent Treatment","authors":"","year":2021,"citation":"Small Methods 5, 2100046 (2021)","doi":"10.1002/smtd.202100046","url":"","note":""},{"title":"Green anti-solvent engineering for high-efficiency and environmentally friendly perovskite solar cells","authors":"Y. Yang et al.","year":2024,"citation":"RSC Advances 14, 32370–32388 (2024)","doi":"10.1039/D4RA05082G","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"process.thermal-annealing","kind":"process","title":"Thermal annealing of perovskite films","aliases":["annealing","thermal treatment","bake"],"tags":["fabrication","annealing","crystallization"],"summary":"Post-deposition heating used to drive solvent removal, phase formation and crystallization in many perovskite fabrication workflows.","facts":["Annealing conditions interact strongly with composition, solvent system, film thickness and substrate stack."],"cautions":["No universal annealing temperature/time should be inferred from this entry."],"related_ids":["formulation.perovskite-precursor-family","formulation.dmf-dmso-solvent-system"],"sources":[{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""},{"title":"Advances in Metal Halide Perovskite Film Preparation: The Role of Anti-Solvent Treatment","authors":"","year":2021,"citation":"Small Methods 5, 2100046 (2021)","doi":"10.1002/smtd.202100046","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"process.thermal-evaporation","kind":"process","title":"Thermal evaporation","aliases":["vacuum evaporation","thermal evaporated","evaporation"],"tags":["fabrication","vacuum","electrode","C60"],"summary":"Vacuum deposition method widely used for metal electrodes and for some molecular or fullerene transport/interfacial layers.","facts":["C60 and metal top contacts are commonly compatible with thermal evaporation in laboratory PSC fabrication."],"cautions":["Deposition rate, substrate temperature and thickness are device-specific process variables."],"related_ids":["material.c60","material.gold","material.silver","material.copper"],"sources":[{"title":"Functionalized fullerene: a key driver for high performance inverted perovskite solar cell","authors":"X. Zhang et al.","year":2025,"citation":"Journal of Energy Chemistry 111, 30–50 (2025)","doi":"10.1016/j.jechem.2025.07.050","url":"","note":""},{"title":"Self-assembled monolayers (SAMs) in inverted perovskite solar cells and their tandem photovoltaics application","authors":"","year":2024,"citation":"Interdisciplinary Materials (2024)","doi":"10.1002/idm2.12145","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"process.surface-treatment","kind":"process","title":"Conductive-oxide surface treatment","aliases":["UV ozone","plasma treatment","surface activation","substrate cleaning"],"tags":["ITO","FTO","SAM","surface","fabrication"],"summary":"Cleaning and surface activation of ITO/FTO before depositing selective contacts or self-assembled monolayers.","facts":["Surface condition influences wetting, work function and adsorption/coverage of molecular interlayers such as phosphonic-acid SAMs."],"cautions":["Treatment chemistry and duration are substrate- and material-specific; excessive treatment can also alter surfaces."],"related_ids":["material.ito","material.fto","material.2pacz","material.meo-2pacz"],"sources":[{"title":"Self-assembled monolayers for perovskite solar cells","authors":"","year":2025,"citation":"Review of Materials Research 1, 100017 (2025)","doi":"10.1016/j.revmat.2025.100017","url":"","note":""},{"title":"Self-assembled monolayers (SAMs) in inverted perovskite solar cells and their tandem photovoltaics application","authors":"","year":2024,"citation":"Interdisciplinary Materials (2024)","doi":"10.1002/idm2.12145","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.low-voc","kind":"diagnostic","title":"Low Voc","aliases":["low Voc","Voc loss","voltage deficit"],"tags":["JV","diagnostic","Voc","recombination"],"summary":"A lower-than-expected open-circuit voltage can indicate increased recombination or unfavorable energetic/selective-contact losses.","facts":["Bulk, grain-boundary and especially interface non-radiative recombination can contribute to Voc loss.","Energy-level mismatch or insufficiently selective contacts can also contribute."],"cautions":["JV alone cannot identify the dominant recombination location; corroborate with optical/electrical measurements and controls."],"related_ids":["concept.voc","concept.nonradiative-recombination","formulation.interface-passivation"],"sources":[{"title":"Minimizing Voltage Losses in Perovskite Solar Cells","authors":"P. Chen, Y. Bai, L. Wang","year":2021,"citation":"Small Structures 2, 2000050 (2021)","doi":"10.1002/sstr.202000050","url":"","note":""},{"title":"Nonradiative Recombination in Perovskite Solar Cells: The Role of Interfaces","authors":"C. M. Wolff et al.","year":2019,"citation":"Advanced Materials 31, 1902762 (2019)","doi":"10.1002/adma.201902762","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.low-jsc","kind":"diagnostic","title":"Low Jsc","aliases":["low Jsc","current loss","low photocurrent"],"tags":["JV","diagnostic","Jsc","collection"],"summary":"A lower-than-expected short-circuit current density indicates reduced photogeneration and/or incomplete collection of photogenerated carriers.","facts":["Possible contributors include optical loss, incomplete absorber coverage, poor collection, transport barriers or measurement/area errors."],"cautions":["Do not assign a single material cause from Jsc alone; cross-check EQE/optics, active area and repeatability when available."],"related_ids":["concept.jsc","diagnostic.high-series-resistance","diagnostic.s-shaped-jv"],"sources":[{"title":"Photovoltaic solar cell technologies: analysing the state of the art","authors":"P. K. Nayak et al.","year":2019,"citation":"Nature Reviews Materials 4, 269–285 (2019)","doi":"10.1038/s41578-019-0097-0","url":"","note":""},{"title":"Promises and challenges of perovskite solar cells","authors":"J.-P. Correa-Baena et al.","year":2017,"citation":"Science 358, 739–744 (2017)","doi":"10.1126/science.aam6323","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.low-ff","kind":"diagnostic","title":"Low fill factor","aliases":["low FF","fill factor loss","poor fill factor"],"tags":["JV","diagnostic","FF","resistance","recombination"],"summary":"A low FF means the JV curve delivers less maximum power than expected from its Voc and Jsc.","facts":["Possible causes include series resistance, leakage/shunt paths, interfacial transport barriers, recombination and dynamic JV behavior."],"cautions":["FF is a compound metric; diagnose with curve shape and complementary measurements rather than a single threshold."],"related_ids":["concept.fill-factor","diagnostic.high-series-resistance","diagnostic.low-shunt-resistance","diagnostic.s-shaped-jv"],"sources":[{"title":"Fill Factor Losses and Deviations from the Superposition Principle in Lead Halide Perovskite Solar Cells","authors":"D. Grabowski et al.","year":2022,"citation":"Solar RRL 6, 2200507 (2022)","doi":"10.1002/solr.202200507","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.high-series-resistance","kind":"diagnostic","title":"High effective series resistance","aliases":["high Rs","series resistance loss","resistive loss"],"tags":["JV","diagnostic","Rs","FF","transport"],"summary":"High effective Rs is a plausible cause of reduced FF and rounded JV behavior near the maximum-power region.","facts":["Contact resistance, transport-layer conductivity and geometry can contribute to effective series resistance."],"cautions":["Rs estimates from JV slopes are model-dependent and can be confounded by non-steady-state behavior in perovskites."],"related_ids":["concept.series-resistance","diagnostic.low-ff"],"sources":[{"title":"Series Resistance Measurements of Perovskite Solar Cells Using Jsc–Voc Measurements","authors":"N. Mundhaas et al.","year":2019,"citation":"Solar RRL 3, 1800378 (2019)","doi":"10.1002/solr.201800378","url":"","note":""},{"title":"Fill Factor Losses and Deviations from the Superposition Principle in Lead Halide Perovskite Solar Cells","authors":"D. Grabowski et al.","year":2022,"citation":"Solar RRL 6, 2200507 (2022)","doi":"10.1002/solr.202200507","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.low-shunt-resistance","kind":"diagnostic","title":"Low effective shunt resistance","aliases":["low Rsh","shunt leakage","leakage current"],"tags":["JV","diagnostic","Rsh","leakage","FF"],"summary":"Low effective Rsh is consistent with parasitic leakage that weakens the JV curve around short circuit and can reduce FF.","facts":["Physical pinholes, edge leakage or defective interfaces can produce shunt-like behavior."],"cautions":["Illuminated “photoshunt” behavior can also arise from transport limitations and field screening, so a low fitted Rsh is not proof of a physical pinhole."],"related_ids":["concept.shunt-resistance","diagnostic.low-ff"],"sources":[{"title":"Fill Factor Losses and Deviations from the Superposition Principle in Lead Halide Perovskite Solar Cells","authors":"D. Grabowski et al.","year":2022,"citation":"Solar RRL 6, 2200507 (2022)","doi":"10.1002/solr.202200507","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.forward-reverse-mismatch","kind":"diagnostic","title":"Forward/reverse JV mismatch","aliases":["forward reverse mismatch","reverse forward mismatch","scan direction mismatch"],"tags":["JV","diagnostic","hysteresis","scan direction"],"summary":"A difference between forward and reverse JV scans is evidence of dynamic, history-dependent device response and is commonly described as JV hysteresis.","facts":["The magnitude and even sign of the mismatch can depend on scan direction, pre-poling and scan rate."],"cautions":["Use correlated scan protocols and report measurement history before comparing hysteresis between samples."],"related_ids":["concept.jv-hysteresis","diagnostic.scan-rate-sensitivity","diagnostic.mpp-scan-mismatch"],"sources":[{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""},{"title":"Origin and alleviation of J-V hysteresis in perovskite solar cells: A short review","authors":"","year":2021,"citation":"Catalysis Today 374, 86–101 (2021)","doi":"10.1016/j.cattod.2020.12.025","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.scan-rate-sensitivity","kind":"diagnostic","title":"JV scan-rate sensitivity","aliases":["scan rate dependence","sweep rate dependence","JV dynamics"],"tags":["JV","diagnostic","hysteresis","scan rate"],"summary":"Strong changes in JV parameters with scan rate indicate that the measurement is probing device dynamics rather than a single stationary current-voltage relation.","facts":["Very fast or very slow scans can sometimes mask hysteresis that is visible at intermediate rates."],"cautions":["Do not interpret one scan rate as definitive evidence of hysteresis-free operation."],"related_ids":["concept.jv-hysteresis","diagnostic.forward-reverse-mismatch"],"sources":[{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.s-shaped-jv","kind":"diagnostic","title":"S-shaped JV curve","aliases":["S shape","S-shaped IV","S-kink","JV kink"],"tags":["JV","diagnostic","barrier","interface","FF"],"summary":"An S-shaped deformation of the illuminated JV curve is commonly associated with extraction barriers, interfacial energetics or transport/selectivity problems.","facts":["S-shaped behavior can strongly suppress fill factor and may arise from contact or interfacial charge-extraction limitations."],"cautions":["Multiple mechanisms can generate similar curve shapes; the JV curve alone is not sufficient to identify the microscopic origin."],"related_ids":["diagnostic.low-ff","diagnostic.low-jsc","architecture.selective-contacts"],"sources":[{"title":"Origins of the s-shape characteristic in J-V curve of inverted-type perovskite solar cells","authors":"S.-E. Chiang et al.","year":2020,"citation":"Nanotechnology 31, 115403 (2020)","doi":"10.1088/1361-6528/ab5a02","url":"","note":""},{"title":"Fill Factor Losses and Deviations from the Superposition Principle in Lead Halide Perovskite Solar Cells","authors":"D. Grabowski et al.","year":2022,"citation":"Solar RRL 6, 2200507 (2022)","doi":"10.1002/solr.202200507","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.mpp-scan-mismatch","kind":"diagnostic","title":"MPP output does not match scan-derived PCE","aliases":["steady state mismatch","MPP mismatch","stabilized PCE mismatch"],"tags":["JV","diagnostic","MPP","hysteresis","measurement"],"summary":"A difference between stabilized/MPP output and the apparent maximum power from a JV scan indicates that the scan may not represent sustained operation.","facts":["Dynamic JV hysteresis and preconditioning can overestimate or underestimate scan-derived performance."],"cautions":["Check stabilization duration, illumination conditions and tracking procedure before declaring one value “true”."],"related_ids":["concept.stabilized-power-output","concept.jv-hysteresis"],"sources":[{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""},{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.unstable-power-output","kind":"diagnostic","title":"Unstable power output under illumination","aliases":["power drift","MPP drift","unstable PCE"],"tags":["stability","diagnostic","MPP","degradation"],"summary":"Power that drifts appreciably under constant illumination/bias can reflect reversible device dynamics, degradation or changing measurement conditions.","facts":["Perovskite devices can show reversible and irreversible changes associated with light, temperature, bias and ambient exposure."],"cautions":["Separate short-term stabilization dynamics from long-term degradation and report atmosphere, temperature, bias and illumination."],"related_ids":["concept.stabilized-power-output","diagnostic.forward-reverse-mismatch"],"sources":[{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.bias-induced-instability","kind":"diagnostic","title":"Bias-induced instability","aliases":["bias stress","electrical bias degradation","ion migration under bias"],"tags":["stability","bias","ions","degradation"],"summary":"Electrical bias can drive ionic redistribution and other electrochemical or interfacial changes in perovskite devices.","facts":["Both operating bias and dark-bias stress can influence device state and subsequent measurements."],"cautions":["Bias-induced change can be partly reversible; distinguish recovery from permanent degradation."],"related_ids":["concept.jv-hysteresis","diagnostic.unstable-power-output"],"sources":[{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.environmental-degradation","kind":"diagnostic","title":"Ambient / environmental degradation","aliases":["air degradation","humidity degradation","moisture degradation"],"tags":["stability","humidity","oxygen","temperature","light"],"summary":"Moisture, oxygen, temperature and illumination can interact with perovskite materials, transport layers and electrodes to drive degradation.","facts":["Encapsulation and controlled-atmosphere testing are important for separating intrinsic from ambient-induced degradation."],"cautions":["Do not compare lifetime values without matching stress conditions and reporting protocol."],"related_ids":["diagnostic.unstable-power-output"],"sources":[{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"diagnostic.device-variability","kind":"diagnostic","title":"Device-to-device variability","aliases":["sample variability","batch variability","reproducibility"],"tags":["statistics","reproducibility","device","batch"],"summary":"Spread across nominally identical devices is an important part of perovskite experiment interpretation and should be considered alongside champion values.","facts":["Perovskite stability and performance studies benefit from reporting the number of samples and distributions rather than only one champion device."],"cautions":["A single best device is insufficient to characterize process reproducibility."],"related_ids":["concept.pce"],"sources":[{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"concept.eqe","kind":"concept","title":"External quantum efficiency","aliases":["EQE","IPCE","external quantum efficiency"],"tags":["measurement","spectral-response","photovoltaic"],"summary":"EQE measures the fraction of incident photons at each wavelength that contribute collected charge in the external circuit.","facts":["Integrating EQE against a reference solar spectrum provides an independent estimate of short-circuit current density.","EQE is a useful cross-check for JV-derived photocurrent but has its own calibration and spectral assumptions."],"cautions":["Agreement between EQE-integrated current and JV Jsc should not be assumed automatically in perovskite devices."],"related_ids":["concept.jsc","diagnostic.eqe-jsc-mismatch"],"sources":[{"title":"A systematic discrepancy between the short circuit current and the integrated quantum efficiency in perovskite solar cells","authors":"M. Saliba et al.","year":2023,"citation":"Nature Communications 14, 5445 (2023)","doi":"10.1038/s41467-023-41263-0","url":"","note":""},{"title":"Photovoltaic solar cell technologies: analysing the state of the art","authors":"P. K. Nayak et al.","year":2019,"citation":"Nature Reviews Materials 4, 269–285 (2019)","doi":"10.1038/s41578-019-0097-0","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.eqe-integrated-jsc","kind":"concept","title":"EQE-integrated short-circuit current density","aliases":["Jsc,EQE","integrated EQE current","Jsc EQE"],"tags":["EQE","Jsc","measurement","quality-check"],"summary":"Short-circuit current density calculated by integrating the measured EQE spectrum against a reference illumination spectrum.","facts":["It provides a measurement route independent from the JV scan for checking photocurrent consistency.","A published analysis of more than 16,000 perovskite reports found a systematic average difference between JV-derived and EQE-integrated Jsc."],"cautions":["A mismatch can arise from device physics, calibration, spectral mismatch, integration choices or measurement conditions; it is not by itself a unique diagnosis."],"related_ids":["concept.eqe","concept.jsc","diagnostic.eqe-jsc-mismatch"],"sources":[{"title":"A systematic discrepancy between the short circuit current and the integrated quantum efficiency in perovskite solar cells","authors":"M. Saliba et al.","year":2023,"citation":"Nature Communications 14, 5445 (2023)","doi":"10.1038/s41467-023-41263-0","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.active-area","kind":"concept","title":"Active area and aperture area","aliases":["active area","device area","aperture area","mask area"],"tags":["measurement","area","JV","reporting"],"summary":"The area used to normalize photovoltaic current and power strongly affects reported current density and efficiency.","facts":["Small research cells are particularly sensitive to edge effects and illumination outside the intended device area.","A defined aperture or mask can improve area definition when used and reported carefully."],"cautions":["Masking can itself perturb measured Voc and fill factor; report both device and aperture geometry rather than treating masking as automatically error-free."],"related_ids":["concept.jsc","concept.pce","concept.aperture-mask","diagnostic.area-mask-sensitivity"],"sources":[{"title":"Effects of Masking on Open-Circuit Voltage and Fill Factor in Solar Cells","authors":"D. Kiermasch et al.","year":2019,"citation":"Joule 3, 16–26 (2019)","doi":"10.1016/j.joule.2018.10.016","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.aperture-mask","kind":"concept","title":"Aperture mask in photovoltaic measurement","aliases":["mask","aperture","shadow mask"],"tags":["measurement","area","mask","JV"],"summary":"An opaque mask with a defined opening used to control the illuminated area during photovoltaic characterization.","facts":["Masks can reduce current overestimation from stray light and edge collection in small-area research devices."],"cautions":["The aperture geometry and alignment can also affect Voc, fill factor and current; masking is part of the measurement protocol and should be documented."],"related_ids":["concept.active-area","diagnostic.area-mask-sensitivity"],"sources":[{"title":"Effects of Masking on Open-Circuit Voltage and Fill Factor in Solar Cells","authors":"D. Kiermasch et al.","year":2019,"citation":"Joule 3, 16–26 (2019)","doi":"10.1016/j.joule.2018.10.016","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.scan-rate","kind":"concept","title":"JV scan rate","aliases":["scan rate","sweep rate","voltage scan rate"],"tags":["JV","measurement","hysteresis","protocol"],"summary":"The rate at which voltage is swept during a JV measurement.","facts":["Perovskite JV curves can depend strongly on scan rate because device response includes slower ionic and interfacial dynamics.","Comparing measurements taken at different scan rates can reveal dynamic behavior that a single scan may hide."],"cautions":["A scan rate that appears hysteresis-free does not guarantee that the curve represents stationary device performance."],"related_ids":["concept.jv-hysteresis","concept.preconditioning","diagnostic.scan-rate-sensitivity"],"sources":[{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.scan-direction","kind":"concept","title":"JV scan direction","aliases":["forward scan","reverse scan","scan direction","F-R","R-F"],"tags":["JV","measurement","hysteresis","protocol"],"summary":"The direction in which voltage is swept during JV characterization, commonly forward or reverse.","facts":["Forward and reverse scans can yield different apparent photovoltaic parameters in perovskite devices.","Correlated double scans can provide more information about dynamic hysteresis than one isolated sweep."],"cautions":["Neither scan direction should automatically be treated as the true steady-state efficiency."],"related_ids":["concept.jv-hysteresis","diagnostic.forward-reverse-mismatch"],"sources":[{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.preconditioning","kind":"concept","title":"Device preconditioning before JV measurement","aliases":["pre-poling","preconditioning","light soaking","measurement history"],"tags":["JV","measurement","hysteresis","protocol"],"summary":"Electrical and optical conditions applied before a JV scan can change the transient state from which the measurement starts.","facts":["Pre-poling voltage, illumination history and delay times can change apparent hysteresis and performance."],"cautions":["Comparisons are weak when preconditioning is unspecified or differs between measurements."],"related_ids":["concept.jv-hysteresis","concept.scan-rate","diagnostic.preconditioning-sensitivity"],"sources":[{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.operational-stability","kind":"concept","title":"Operational stability","aliases":["stability","operational lifetime","aging","ISOS"],"tags":["stability","measurement","degradation"],"summary":"Operational stability describes how photovoltaic output evolves while a device is exposed to defined operating stresses such as illumination, temperature and electrical bias.","facts":["Consistent test conditions and reporting are necessary to compare degradation data across laboratories.","Perovskite-specific stability testing benefits from tracking reversible and irreversible changes separately where possible."],"cautions":["A short stability run is not equivalent to qualification or long service lifetime."],"related_ids":["concept.isos-protocols","concept.stabilized-power-output","diagnostic.unstable-power-output"],"sources":[{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.isos-protocols","kind":"concept","title":"ISOS-style stability protocols","aliases":["ISOS","ISOS-L","ISOS-D","stability protocol"],"tags":["stability","protocol","reporting","reproducibility"],"summary":"ISOS-derived procedures provide shared test and reporting conventions for photovoltaic stability studies, with perovskite-specific adaptations proposed by community consensus.","facts":["Protocols distinguish stress conditions such as dark storage, illumination, thermal stress and outdoor exposure.","Reporting the environmental and electrical conditions makes stability results easier to reproduce and compare."],"cautions":["These research protocols are not a replacement for formal photovoltaic module qualification standards."],"related_ids":["concept.operational-stability"],"sources":[{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.ion-migration","kind":"concept","title":"Ion migration in metal-halide perovskites","aliases":["ion migration","mobile ions","ionic redistribution"],"tags":["ions","hysteresis","stability","perovskite"],"summary":"Mobile ionic species can redistribute in metal-halide perovskites under electrical, thermal or illumination-driven conditions.","facts":["Ion migration is associated with time-dependent internal fields, interfacial changes, hysteresis and some degradation pathways.","Its impact depends on composition, interfaces, architecture and operating conditions."],"cautions":["A dynamic JV signature alone does not uniquely prove a specific migrating species or pathway."],"related_ids":["concept.jv-hysteresis","diagnostic.bias-induced-instability","concept.operational-stability"],"sources":[{"title":"Ion migration in perovskite solar cells","authors":"J. Thiesbrummel et al.","year":2026,"citation":"Nature Reviews Chemistry 10, 179–195 (2026)","doi":"10.1038/s41570-025-00790-8","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"concept.reproducibility","kind":"concept","title":"Device-to-device reproducibility","aliases":["reproducibility","repeatability","batch variation","distribution"],"tags":["statistics","reproducibility","device-variability"],"summary":"Photovoltaic conclusions are stronger when they describe distributions across devices or batches rather than only the champion cell.","facts":["Device-to-device variability can reveal process sensitivity that is invisible in one selected device.","Report sample counts and distribution statistics when comparing fabrication conditions."],"cautions":["Differences between batches can confound a treatment comparison if controls are not fabricated and measured under comparable conditions."],"related_ids":["diagnostic.device-variability"],"sources":[{"title":"Photovoltaic solar cell technologies: analysing the state of the art","authors":"P. K. Nayak et al.","year":2019,"citation":"Nature Reviews Materials 4, 269–285 (2019)","doi":"10.1038/s41578-019-0097-0","url":"","note":""},{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.dmf","kind":"material","title":"Dimethylformamide (DMF)","aliases":["DMF","N,N-dimethylformamide"],"tags":["solvent","precursor","perovskite"],"summary":"Polar aprotic solvent widely used in solution processing of metal-halide perovskite precursor inks.","facts":["DMF is commonly combined with coordinating solvents such as DMSO to tune precursor solubility and film formation."],"cautions":["Solvent choice, ratio and drying conditions strongly affect crystallization; a solvent name alone does not define a transferable recipe."],"related_ids":["material.dmso","formulation.dmf-dmso-solvent-system"],"sources":[{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.dmso","kind":"material","title":"Dimethyl sulfoxide (DMSO)","aliases":["DMSO","dimethyl sulfoxide"],"tags":["solvent","coordination","precursor","perovskite"],"summary":"High-boiling coordinating solvent frequently used with DMF in perovskite precursor formulations.","facts":["DMSO can coordinate lead halide species and participate in intermediate phases that influence nucleation and crystallization."],"cautions":["Residual DMSO and the exact solvent ratio can affect film formation, so processing conditions must accompany composition."],"related_ids":["material.dmf","formulation.dmf-dmso-solvent-system"],"sources":[{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.gbl","kind":"material","title":"Gamma-butyrolactone (GBL)","aliases":["GBL","γ-butyrolactone","gamma-butyrolactone"],"tags":["solvent","precursor","perovskite"],"summary":"Polar aprotic solvent used in some perovskite precursor solvent systems.","facts":["GBL can be used alone or in mixed-solvent strategies for solution deposition."],"cautions":["Solubility and drying behavior differ from DMF/DMSO systems; recipes should not be transferred by solvent substitution alone."],"related_ids":["process.solution-deposition"],"sources":[{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.nmp","kind":"material","title":"N-methyl-2-pyrrolidone (NMP)","aliases":["NMP","N-methylpyrrolidone"],"tags":["solvent","coordination","precursor","perovskite"],"summary":"Coordinating polar aprotic solvent used in some mixed-solvent perovskite precursor systems.","facts":["NMP can form coordinated intermediate phases with lead halides and has been used to tune crystallization in ternary solvent systems."],"cautions":["Its high boiling point and coordination strength alter drying and conversion kinetics."],"related_ids":["process.solution-deposition"],"sources":[{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.chlorobenzene","kind":"material","title":"Chlorobenzene","aliases":["CB","chlorobenzene"],"tags":["antisolvent","solvent","spin-coating"],"summary":"Organic solvent widely used as an antisolvent in spin-coated perovskite film formation.","facts":["Antisolvent application can drive rapid supersaturation and crystallization of the wet precursor film."],"cautions":["Chlorobenzene is hazardous and volatile; timing, volume and precursor chemistry strongly affect the result."],"related_ids":["process.antisolvent-quench","formulation.antisolvent-assisted-crystallization"],"sources":[{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""},{"title":"Green anti-solvent engineering for high-efficiency and environmentally friendly perovskite solar cells","authors":"Y. Yang et al.","year":2024,"citation":"RSC Advances 14, 32370–32388 (2024)","doi":"10.1039/D4RA05082G","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.toluene","kind":"material","title":"Toluene","aliases":["toluene"],"tags":["antisolvent","solvent","spin-coating"],"summary":"Organic solvent used as an antisolvent in some perovskite crystallization protocols.","facts":["Toluene can extract or displace precursor solvents during antisolvent-assisted film formation."],"cautions":["It is hazardous and the usable process window depends on precursor solvent chemistry and coating conditions."],"related_ids":["process.antisolvent-quench"],"sources":[{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""},{"title":"Green anti-solvent engineering for high-efficiency and environmentally friendly perovskite solar cells","authors":"Y. Yang et al.","year":2024,"citation":"RSC Advances 14, 32370–32388 (2024)","doi":"10.1039/D4RA05082G","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.diethyl-ether","kind":"material","title":"Diethyl ether","aliases":["ether","Et2O","diethyl ether"],"tags":["antisolvent","solvent","spin-coating"],"summary":"Low-boiling solvent used as an alternative antisolvent in some perovskite film-processing routes.","facts":["Its low boiling point can promote rapid solvent removal during crystallization."],"cautions":["High volatility and flammability make handling and temperature control important; it is not a drop-in replacement for every antisolvent."],"related_ids":["process.antisolvent-quench"],"sources":[{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""},{"title":"Green anti-solvent engineering for high-efficiency and environmentally friendly perovskite solar cells","authors":"Y. Yang et al.","year":2024,"citation":"RSC Advances 14, 32370–32388 (2024)","doi":"10.1039/D4RA05082G","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.anisole","kind":"material","title":"Anisole","aliases":["methoxybenzene","anisole"],"tags":["antisolvent","green-processing","spin-coating"],"summary":"Aromatic ether investigated as a lower-hazard antisolvent for perovskite film formation.","facts":["Some studies report a wider antisolvent processing window with anisole than with conventional aggressive antisolvents."],"cautions":["A wider process window is formulation-dependent and does not eliminate the need to control drip time, volume and environment."],"related_ids":["process.antisolvent-quench"],"sources":[{"title":"Green anti-solvent engineering for high-efficiency and environmentally friendly perovskite solar cells","authors":"Y. Yang et al.","year":2024,"citation":"RSC Advances 14, 32370–32388 (2024)","doi":"10.1039/D4RA05082G","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.fai","kind":"material","title":"Formamidinium iodide (FAI)","aliases":["FAI","formamidinium iodide"],"tags":["precursor","A-site","iodide","perovskite"],"summary":"Formamidinium iodide is a common A-site precursor salt for lead-halide perovskite absorber formulations.","facts":["FA-containing compositions are widely used in mixed-cation perovskites."],"cautions":["The final perovskite composition depends on all precursor stoichiometries and processing; FAI alone does not identify the absorber phase."],"related_ids":["formulation.mixed-cation-composition","material.pbi2"],"sources":[{"title":"Progress on Perovskite Materials and Solar Cells with Mixed Cations and Halide Anions","authors":"L. K. Ono et al.","year":2017,"citation":"ACS Applied Materials & Interfaces 9, 30197–30246 (2017)","doi":"10.1021/acsami.7b06001","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.mai","kind":"material","title":"Methylammonium iodide (MAI)","aliases":["MAI","methylammonium iodide"],"tags":["precursor","A-site","iodide","perovskite"],"summary":"Methylammonium iodide is an A-site precursor salt used in many metal-halide perovskite formulations.","facts":["MAI has been used in single-cation and mixed-cation lead iodide perovskites."],"cautions":["Composition and phase behavior cannot be inferred from the presence of MAI alone."],"related_ids":["formulation.mixed-cation-composition","material.pbi2"],"sources":[{"title":"Progress on Perovskite Materials and Solar Cells with Mixed Cations and Halide Anions","authors":"L. K. Ono et al.","year":2017,"citation":"ACS Applied Materials & Interfaces 9, 30197–30246 (2017)","doi":"10.1021/acsami.7b06001","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.csi","kind":"material","title":"Cesium iodide (CsI)","aliases":["CsI","cesium iodide"],"tags":["precursor","A-site","iodide","perovskite"],"summary":"Cesium iodide is an inorganic A-site precursor used in mixed-cation perovskite compositions.","facts":["Partial Cs incorporation is common in multi-cation absorber formulations."],"cautions":["The effect of Cs depends on composition, fraction and processing; it should not be treated as universally beneficial."],"related_ids":["formulation.mixed-cation-composition"],"sources":[{"title":"Progress on Perovskite Materials and Solar Cells with Mixed Cations and Halide Anions","authors":"L. K. Ono et al.","year":2017,"citation":"ACS Applied Materials & Interfaces 9, 30197–30246 (2017)","doi":"10.1021/acsami.7b06001","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.pbi2","kind":"material","title":"Lead iodide (PbI2)","aliases":["PbI2","lead iodide"],"tags":["precursor","lead-halide","iodide","perovskite"],"summary":"Lead iodide is a primary lead-halide precursor for iodide-containing perovskite absorbers.","facts":["PbI2 interacts with coordinating precursor solvents and organic/inorganic halide salts during film formation."],"cautions":["Residual PbI2 may have different effects depending on location and amount; its presence is not automatically evidence of an optimal film."],"related_ids":["material.fai","material.mai","formulation.perovskite-precursor-family"],"sources":[{"title":"Progress on Perovskite Materials and Solar Cells with Mixed Cations and Halide Anions","authors":"L. K. Ono et al.","year":2017,"citation":"ACS Applied Materials & Interfaces 9, 30197–30246 (2017)","doi":"10.1021/acsami.7b06001","url":"","note":""},{"title":"Solvent engineering for perovskite solar cells: a review","authors":"","year":2020,"citation":"Micro & Nano Letters (2020)","doi":"10.1049/mnl.2019.0735","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.pbbr2","kind":"material","title":"Lead bromide (PbBr2)","aliases":["PbBr2","lead bromide"],"tags":["precursor","lead-halide","bromide","perovskite"],"summary":"Lead bromide is a precursor used to introduce bromide into metal-halide perovskite absorber compositions.","facts":["Br-containing compositions are used to tune halide composition and absorber bandgap."],"cautions":["Mixed-halide absorbers can show light-induced compositional changes; composition alone does not guarantee stable bandgap."],"related_ids":["formulation.mixed-halide-composition"],"sources":[{"title":"Progress on Perovskite Materials and Solar Cells with Mixed Cations and Halide Anions","authors":"L. K. Ono et al.","year":2017,"citation":"ACS Applied Materials & Interfaces 9, 30197–30246 (2017)","doi":"10.1021/acsami.7b06001","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.litfsi","kind":"material","title":"Lithium bis(trifluoromethanesulfonyl)imide (Li-TFSI)","aliases":["Li-TFSI","LiTFSI"],"tags":["dopant","HTL","spiro-OMeTAD","PTAA"],"summary":"Lithium salt commonly used as an additive or dopant in organic hole-transport-layer formulations such as spiro-OMeTAD.","facts":["Li-TFSI is part of widely used doped HTL recipes."],"cautions":["HTL behavior depends on the complete additive formulation, oxidation history and environment; Li-TFSI concentration alone is not a transferable process recipe."],"related_ids":["material.spiro-ometad","material.ptaa"],"sources":[{"title":"Lessons learned from spiro-OMeTAD and PTAA in perovskite solar cells","authors":"F. M. Rombach, S. A. Haque, T. J. Macdonald","year":2021,"citation":"Energy & Environmental Science 14, 5161–5190 (2021)","doi":"10.1039/D1EE02095A","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"material.tbp","kind":"material","title":"4-tert-butylpyridine (tBP)","aliases":["tBP","4-tert-butylpyridine"],"tags":["additive","HTL","spiro-OMeTAD"],"summary":"Organic additive commonly used in doped spiro-OMeTAD hole-transport formulations.","facts":["tBP is often combined with lithium salts in conventional spiro-OMeTAD recipes."],"cautions":["Its concentration and interaction with other additives affect film and device behavior; record the complete HTL recipe."],"related_ids":["material.spiro-ometad","material.litfsi"],"sources":[{"title":"Lessons learned from spiro-OMeTAD and PTAA in perovskite solar cells","authors":"F. M. Rombach, S. A. Haque, T. J. Macdonald","year":2021,"citation":"Energy & Environmental Science 14, 5161–5190 (2021)","doi":"10.1039/D1EE02095A","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"process.mpp-tracking","kind":"process","title":"Maximum-power-point tracking","aliases":["MPPT","MPP tracking","stabilized power tracking"],"tags":["measurement","MPP","stability","photovoltaic"],"summary":"Measurement in which device bias is adjusted or held near the maximum-power point while output is monitored over time.","facts":["MPP tracking provides a steady-state-oriented check on whether scan-derived efficiency reflects sustained output.","It is also used during operational stability tests."],"cautions":["A short MPP trace verifies short-term output but does not establish long-term device stability."],"related_ids":["concept.stabilized-power-output","concept.operational-stability","diagnostic.mpp-scan-mismatch"],"sources":[{"title":"Consensus statement for stability assessment and reporting for perovskite photovoltaics based on ISOS procedures","authors":"M. V. Khenkin et al.","year":2020,"citation":"Nature Energy 5, 35–49 (2020)","doi":"10.1038/s41560-019-0529-5","url":"","note":""},{"title":"A systematic discrepancy between the short circuit current and the integrated quantum efficiency in perovskite solar cells","authors":"M. Saliba et al.","year":2023,"citation":"Nature Communications 14, 5445 (2023)","doi":"10.1038/s41467-023-41263-0","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"process.eqe-measurement","kind":"process","title":"External quantum efficiency measurement","aliases":["EQE measurement","IPCE measurement"],"tags":["measurement","EQE","spectral-response"],"summary":"Spectral measurement of collected photocurrent response as a function of incident wavelength.","facts":["Integrated EQE can be compared with JV-derived Jsc as an independent consistency check."],"cautions":["Calibration, spectral resolution, bias light and dynamic device response can affect the result."],"related_ids":["concept.eqe","concept.eqe-integrated-jsc"],"sources":[{"title":"A systematic discrepancy between the short circuit current and the integrated quantum efficiency in perovskite solar cells","authors":"M. Saliba et al.","year":2023,"citation":"Nature Communications 14, 5445 (2023)","doi":"10.1038/s41467-023-41263-0","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"diagnostic.eqe-jsc-mismatch","kind":"diagnostic","title":"JV Jsc and EQE-integrated Jsc do not agree","aliases":["EQE mismatch","Jsc mismatch","Jsc JV vs EQE"],"tags":["diagnostic","EQE","Jsc","measurement"],"summary":"A mismatch between short-circuit current density from a JV scan and current integrated from EQE is a measurement-quality signal that deserves investigation.","facts":["Possible contributors include calibration, spectral mismatch, integration settings and time-dependent device response.","A broad literature analysis found a systematic average offset in perovskite reports, so small discrepancies are not automatically a single-lab error."],"cautions":["Do not “correct” one value to match the other without identifying the measurement cause."],"related_ids":["concept.eqe-integrated-jsc","concept.jsc"],"sources":[{"title":"A systematic discrepancy between the short circuit current and the integrated quantum efficiency in perovskite solar cells","authors":"M. Saliba et al.","year":2023,"citation":"Nature Communications 14, 5445 (2023)","doi":"10.1038/s41467-023-41263-0","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"diagnostic.area-mask-sensitivity","kind":"diagnostic","title":"Photovoltaic result changes with mask or aperture","aliases":["mask sensitivity","area dependence","aperture dependence"],"tags":["diagnostic","area","mask","JV"],"summary":"Large changes in Jsc, Voc, fill factor or PCE when the illuminated aperture changes indicate that area definition and edge effects need review.","facts":["Small-area laboratory devices can overestimate current density when stray or edge-collected light contributes outside the intended area."],"cautions":["A mask can also perturb voltage and fill factor; document geometry and avoid interpreting an area artifact as a material improvement."],"related_ids":["concept.active-area","concept.aperture-mask"],"sources":[{"title":"Effects of Masking on Open-Circuit Voltage and Fill Factor in Solar Cells","authors":"D. Kiermasch et al.","year":2019,"citation":"Joule 3, 16–26 (2019)","doi":"10.1016/j.joule.2018.10.016","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"diagnostic.preconditioning-sensitivity","kind":"diagnostic","title":"JV result depends on preconditioning","aliases":["preconditioning sensitivity","poling sensitivity","measurement history"],"tags":["diagnostic","JV","hysteresis","protocol"],"summary":"Performance or hysteresis changes substantially when the electrical or illumination history before the scan changes.","facts":["This is consistent with a device that has slow internal dynamics relative to the measurement."],"cautions":["The observation does not identify one unique microscopic mechanism; compare controlled protocols and steady-state measurements."],"related_ids":["concept.preconditioning","concept.ion-migration","concept.jv-hysteresis"],"sources":[{"title":"How measurement protocols influence the dynamic J-V characteristics of perovskite solar cells: Theory and experiment","authors":"G. A. Nemnes et al.","year":2018,"citation":"Solar Energy 173, 976–983 (2018)","doi":"10.1016/j.solener.2018.08.033","url":"","note":""},{"title":"Ion migration in perovskite solar cells","authors":"J. Thiesbrummel et al.","year":2026,"citation":"Nature Reviews Chemistry 10, 179–195 (2026)","doi":"10.1038/s41570-025-00790-8","url":"","note":""}],"status":"active","created_at":"2026-09-12T00:00:00.000Z","updated_at":"2026-09-12T00:00:00.000Z"},{"id":"guide.getting-started","kind":"guide","title":"Getting started","aliases":["Getting started","getting started"],"tags":["LabFlow","app","help","workflow","getting-started"],"summary":"The shortest path from a ZIP archive to trustworthy Results with minimal researcher interaction.","facts":["3. Let LabFlow normalize names, rebuild hierarchy and analyze data; review any mechanically safe cleanup it detects and accept it explicitly before LabFlow Data is changed.","4. If Review says Scientific decisions: Clear, go directly to Results.","5. If ambiguities remain, click Resolve with AI, inspect the suggestions and optionally Apply all suggestions.","6. Use Design or Export when needed. NOMAD artifacts live inside Export.","That is the intended normal workflow. Researchers should not have to understand the internal pipeline to get trustworthy deterministic Results.","LabFlow performs no AI request. It automatically:","creates Experiment/Sample/Run/Measurement relationships;"],"cautions":["This entry describes LabFlow operation; it is not scientific evidence about the current experiment."],"related_ids":[],"sources":[{"title":"Getting started","authors":"LabFlow documentation","year":null,"citation":"docs/guides/GETTING_STARTED.md","doi":"","url":"","note":"Canonical local documentation"}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"guide.research-workflow","kind":"guide","title":"Research workflow","aliases":["Research workflow","research workflow"],"tags":["LabFlow","app","help","workflow","research-workflow"],"summary":"Understand what each LabFlow step owns, what it produces, and where researcher review is required.","facts":["The workflow is intentionally linear and uses one shared experiment state.","Pages do not own separate scientific copies. A reviewed change to the LabFlow Data is therefore visible wherever that field matters.","The first step establishes provenance and current data quality. Import is deterministic-first and remains usable without AI.","Review distinguishes mechanically safe deterministic corrections from ambiguous interpretations. Safe corrections are detected automatically but remain pending until Apply safe corrections; acceptance changes only LabFlow Data, writes provenance, and immediately reruns the deterministic pipeline. Apply only changes whose evidence and target you understand.","Results reuse deterministic calculations from the current revision. Filters and charts change the view, not the underlying measurements. AI interpretation is read-only prose layered over these values.","Design is directly editable. AI suggestions are optional proposals and never silently overwrite known fields.","Bulk suggestion is sequential/bounded. A provider throttle stops the sequence immediately and preserves completed proposals instead of converting every remaining experiment into an error."],"cautions":["This entry describes LabFlow operation; it is not scientific evidence about the current experiment."],"related_ids":[],"sources":[{"title":"Research workflow","authors":"LabFlow documentation","year":null,"citation":"docs/guides/RESEARCH_WORKFLOW.md","doi":"","url":"","note":"Canonical local documentation"}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"guide.ai-assistance","kind":"guide","title":"AI assistance","aliases":["AI assistance","ai assistance"],"tags":["LabFlow","app","help","workflow","ai-assistance"],"summary":"Where AI helps, where it is deliberately absent, and what every AI result means.","facts":["ZIP parsing, naming normalization, safe-cleanup detection, hierarchy validation and Results are deterministic. Applying a detected safe cleanup is an explicit researcher decision and does not require AI.","dataset.resolve-ambiguities suggests mappings/classifications only when deterministic rules cannot settle semantic meaning. Suggestions are stored for review, not silently applied.","design.infer completes missing qualitative solution chemistry, a complete device architecture and/or fabrication process for one incomplete experiment. One absorber layer is still incomplete. One run attempts every missing domain; incomplete model output is retried internally. For multiple experiments, Complete all missing with AI runs the same Action sequentially. If bounded retries are exhausted, that experiment becomes a retryable Action error rather than a second “Suggest missing” / “Needs context” state.","results.interpret produces a structured, evidence-bounded interpretation of deterministic statistics/findings.","results.compare explains differences between two or more selected groups without recalculating anything.","assistant.chat answers questions from bounded page/experiment context and cannot mutate scientific data.","Model output is either a proposal, a derived annotation, or a read-only answer. Scientific measurements and researcher-confirmed Design values are not overwritten automatically."],"cautions":["This entry describes LabFlow operation; it is not scientific evidence about the current experiment."],"related_ids":[],"sources":[{"title":"AI assistance","authors":"LabFlow documentation","year":null,"citation":"docs/guides/AI_ASSISTANCE.md","doi":"","url":"","note":"Canonical local documentation"}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"guide.ai-tokens-and-rate-limits","kind":"guide","title":"AI tokens, limits and rate limiting","aliases":["AI tokens, limits and rate limiting","ai tokens and rate limits"],"tags":["LabFlow","app","help","workflow","ai-tokens-and-rate-limits"],"summary":"Current Action budgets, semantic retries and provider throttling behavior.","facts":["AI requests are bounded by several independent controls:","provider/model context and completion limits;","The Action manifest, not the theoretical model maximum, defines LabFlow's operational budget.","Do not duplicate hardcoded budget tables in prose. The generated docs/reference/ACTION_RUNTIME_MATRIX.md is the source of truth and is rebuilt from actions/*/action.json.","Current structured AI Actions use at most one bounded semantic retry. If an Action has validate_with, a rejected proposal causes the AI step to regenerate with validator feedback.","Provider throttling/429 responses are not silently replayed by the transport.","Complete all missing with AI is a sequence of independent design.infer runs for multiple incomplete experiments. Each run attempts all missing domains and uses bounded internal retries. Completed suggestions remain stored if a later experiment fails. Provider rate limiting stops subsequent requests rather than creating hidden background traffic."],"cautions":["This entry describes LabFlow operation; it is not scientific evidence about the current experiment."],"related_ids":[],"sources":[{"title":"AI tokens, limits and rate limiting","authors":"LabFlow documentation","year":null,"citation":"docs/guides/AI_TOKENS_AND_RATE_LIMITS.md","doi":"","url":"","note":"Canonical local documentation"}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"guide.knowledge-base","kind":"guide","title":"Scientific Knowledge Base","aliases":["Scientific Knowledge Base","knowledge base"],"tags":["LabFlow","app","help","workflow","knowledge-base"],"summary":"Sourced scientific reference knowledge stored as portable JSONL, without a separate database service.","facts":["LabFlow's Knowledge Base (KB) provides sourced scientific background to the Assistant and Design inference without adding a backend, vector database, embeddings service or a second scientific data model.","The researcher-facing model is intentionally simple:","Built-in library — curated, read-only scientific references shipped with LabFlow.","My JSONL library — references added or imported by the researcher and stored as plain JSON Lines.","The default distribution contains a curated starter corpus focused on perovskite photovoltaics and JV interpretation. It covers device architectures, materials and precursor chemistry, formulations, process families, photovoltaic measurements, stability concepts and common diagnostic patterns.","The bundled corpus avoids presenting recipe-specific spin speeds, concentrations, annealing temperatures, layer thicknesses or treatment times as universal recommendations. Such values depend on chemistry, substrate, equipment and literature protocol. Entries emphasize reusable relationships and cautions with traceable literature sources.","Use it for reusable reference knowledge such as:"],"cautions":["This entry describes LabFlow operation; it is not scientific evidence about the current experiment."],"related_ids":[],"sources":[{"title":"Scientific Knowledge Base","authors":"LabFlow documentation","year":null,"citation":"docs/guides/KNOWLEDGE_BASE.md","doi":"","url":"","note":"Canonical local documentation"}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"guide.lab-cabinet","kind":"guide","title":"Lab Cabinet","aliases":["Lab Cabinet","lab cabinet"],"tags":["LabFlow","app","help","workflow","lab-cabinet"],"summary":"Save lab recipes once and reuse them safely in future Design experiments.","facts":["Lab Cabinet is the place for things you repeatedly type into Design: formulations, device stacks, process recipes, substrates, materials and instrument references.","1. Save something useful from a Design, or create it once in Cabinet.","2. Reuse it in another Design instead of retyping it.","3. Keep experiments independent: LabFlow copies the current values into the experiment, so changing the Cabinet later never rewrites past experiment data.","It is deliberately not stock management, inventory, ERP or LIMS.","For most researchers the three main Cabinet resources are:","Formulations — precursor solutions, passivation solutions or other reusable chemistry definitions."],"cautions":["This entry describes LabFlow operation; it is not scientific evidence about the current experiment."],"related_ids":[],"sources":[{"title":"Lab Cabinet","authors":"LabFlow documentation","year":null,"citation":"docs/guides/LAB_CABINET.md","doi":"","url":"","note":"Canonical local documentation"}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"},{"id":"guide.troubleshooting","kind":"guide","title":"Troubleshooting","aliases":["Troubleshooting","troubleshooting"],"tags":["LabFlow","app","help","workflow","troubleshooting"],"summary":"Diagnose import, Action, provider and structured-output failures without confusing scientific uncertainty with technical errors.","facts":["A healthy import finishes without any AI request. Check:","The pipeline should be ready; Review may still contain semantic decisions, which is not an import failure.","Canonical naming is deterministic. If a scientific token is genuinely ambiguous, Review should expose it rather than silently guessing.","This is a structured/semantic contract failure. Logs include invalid JSON/schema/semantic details where available. For design.infer, incomplete coverage is retried inside the same Action; only after bounded retries are exhausted does the selected experiment expose Retry inference.","The model/server stopped before returning a complete usable output. Reduce model verbosity/context or use a model with sufficient completion capacity.","The request exceeds the configured model/server context. Inspect the Action's bounded input/output budget and local server context size.","LabFlow surfaces provider throttling and does not create hidden automatic request loops. Retry later or use another configured provider/model."],"cautions":["This entry describes LabFlow operation; it is not scientific evidence about the current experiment."],"related_ids":[],"sources":[{"title":"Troubleshooting","authors":"LabFlow documentation","year":null,"citation":"docs/guides/TROUBLESHOOTING.md","doi":"","url":"","note":"Canonical local documentation"}],"status":"active","created_at":"2026-09-10T00:00:00.000Z","updated_at":"2026-09-10T00:00:00.000Z"}]};
